            String name = tier.getPriority().name();
            targetSeries.getData().add(new XYChart.Data<>(name, tier.getTargetSharePercent().doubleValue()));
            actualSeries.getData().add(new XYChart.Data<>(name, tier.getActualSharePercent().doubleValue()));
        }

        barChart.getData().addAll(targetSeries, actualSeries);
        return barChart;
    }
}

