        List<PriorityAlignmentService.PriorityRankRow> ranking) {
    TableView<PriorityAlignmentService.PriorityRankRow> table =
            new TableView<>(FXCollections.observableArrayList(ranking));

    TableColumn<PriorityAlignmentService.PriorityRankRow, Number> priorityRankCol = new TableColumn<>("Priority Rank");
    priorityRankCol.setCellValueFactory(cell -> new SimpleIntegerProperty(cell.getValue().getPriorityRank()));

    TableColumn<PriorityAlignmentService.PriorityRankRow, String> nameCol = new TableColumn<>("Category");
    nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getCategory().getName()));

    TableColumn<PriorityAlignmentService.PriorityRankRow, Number> spendRankCol = new TableColumn<>("Spend Rank");
    spendRankCol.setCellValueFactory(cell -> new SimpleIntegerProperty(cell.getValue().getSpendRank()));

    TableColumn<PriorityAlignmentService.PriorityRankRow, BigDecimal> actualCol = new TableColumn<>("Actual");
    actualCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getActual()));

    table.getColumns().addAll(priorityRankCol, nameCol, spendRankCol, actualCol);

    table.setRowFactory(tv -> new TableRow<>() {
        @Override
        protected void updateItem(PriorityAlignmentService.PriorityRankRow item, boolean empty) {
            super.updateItem(item, empty);
            setStyle(!empty && item != null && !item.matchesSpendRank() ? "-fx-background-color: #f8d7da;" : "");
        }
    });

    return table;
}

