void summarizePriorityAlignmentSplitsTargetAndActualSharesByTier(@TempDir Path tempDir) {
    DataPaths dataPaths = new DataPaths(tempDir);
    CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
    TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
    MonthSummaryService monthSummaryService =
            buildMonthSummaryService(tempDir, categoryRepository, transactionRepository);

    categoryRepository.add(new Category("Rent", new BigDecimal("800.00"), Priority.ESSENTIAL));
    categoryRepository.add(new Category("Entertainment", new BigDecimal("200.00"), Priority.DISCRETIONARY));

    YearMonth august = YearMonth.of(2026, 8);
    transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Rent",
            new BigDecimal("800.00"), "august rent");
    transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Entertainment",
            new BigDecimal("400.00"), "overspent on fun");

    PriorityAlignmentService.PriorityAlignmentReport report = monthSummaryService.summarizePriorityAlignment(august);

    PriorityAlignmentService.TierAlignment essential = report.getTiers().stream()
            .filter(t -> t.getPriority() == Priority.ESSENTIAL).findFirst().orElseThrow();
