package com.example.finance;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * For a given month, ranks the categories that have been given a priority
 * number against how they actually rank by spend, so the user can see
 * where the two orderings line up or diverge. Only categories with a
 * priority set participate — an unprioritized category has nothing to
 * compare against, and would otherwise distort the spend ranking for the
 * categories that do.
 */
public class PriorityAlignmentService {

    private final BudgetService budgetService;

    public PriorityAlignmentService(BudgetService budgetService) {
        this.budgetService = budgetService;
    }

    public List<PriorityRankRow> rankingForMonth(YearMonth month) {
        List<BudgetService.CategoryTotal> prioritized = budgetService.categoryTotals(month).stream()
                .filter(t -> !t.isIncomeOnly())
                .filter(t -> t.getCategory().getPriority().isPresent())
                .toList();

        List<BudgetService.CategoryTotal> bySpendDesc = prioritized.stream()
                .sorted(Comparator.comparing(BudgetService.CategoryTotal::getActual, Comparator.reverseOrder())
                        .thenComparing(t -> t.getCategory().getName()))
                .toList();
        Map<String, Integer> spendRankByCategoryName = new HashMap<>();
        for (int i = 0; i < bySpendDesc.size(); i++) {
            spendRankByCategoryName.put(bySpendDesc.get(i).getCategory().getName(), i + 1);
        }

        return prioritized.stream()
                .sorted(Comparator.<BudgetService.CategoryTotal>comparingInt(t -> t.getCategory().getPriority().orElseThrow())
                        .thenComparing(t -> t.getCategory().getName()))
                .map(t -> new PriorityRankRow(t.getCategory(), t.getCategory().getPriority().orElseThrow(),
                        spendRankByCategoryName.get(t.getCategory().getName()), t.getActual()))
                .toList();
    }

    public static class PriorityRankRow {
        private final Category category;
        private final int priorityRank;
        private final int spendRank;
        private final BigDecimal actual;

        public PriorityRankRow(Category category, int priorityRank, int spendRank, BigDecimal actual) {
            this.category = category;
            this.priorityRank = priorityRank;
            this.spendRank = spendRank;
            this.actual = actual;
        }

        public Category getCategory() {
            return category;
        }

        public int getPriorityRank() {
            return priorityRank;
        }

        public int getSpendRank() {
            return spendRank;
        }

        public BigDecimal getActual() {
            return actual;
        }

        public boolean matchesSpendRank() {
            return priorityRank == spendRank;
        }
    }
}

